const experienceCodes = {
  'internship': '1',
  'entry level': '2',
  'associate': '3',
  'mid-senior level': '4',
  'director': '5',
  'executive': '6',
}

const remoteCodes = {
  'on-site': '1',
  'remote': '2',
  'hybrid': '3',
}

function toCodes(value, codes) {
  if (!value) return ''
  return String(value)
    .split(',')
    .map((v) => codes[v.trim().toLowerCase()])
    .filter(Boolean)
    .join(',')
}

const results = []

for (const item of $input.all()) {
  const row = item.json
  let url = 'https://www.linkedin.com/jobs/search/?f_TPR=r86400'

  if (row.Keyword) url += `&keywords=${encodeURIComponent(row.Keyword)}`
  if (row.Location) url += `&location=${encodeURIComponent(row.Location)}`

  const experience = toCodes(row['Experience Level'], experienceCodes)
  if (experience) url += `&f_E=${experience}`

  const remote = toCodes(row.Remote, remoteCodes)
  if (remote) url += `&f_WT=${remote}`

  if (row['Easy Apply']) url += '&f_EA=true'

  results.push({ json: { url } })
}

return results

