const relevant = /front-?end|vue|node|react|javascript|typescript|web-dev|ui-dev|full-?stack|sviluppatore-web|(^|-)ai(-|$)|genai|generative|llm|intelligenza-artificiale/i
const priority = /vue|node/i

const jobs = $input.all().filter((item) => {
  const link = String(item.json.jobs || '')
  return link.includes('it.linkedin.com') && relevant.test(link.split('?')[0])
})

jobs.sort((a, b) => {
  const aFirst = priority.test(a.json.jobs.split('?')[0]) ? 0 : 1
  const bFirst = priority.test(b.json.jobs.split('?')[0]) ? 0 : 1
  return aFirst - bFirst
})

return jobs
